+export function checkQueryPredicates(world: World, query: QueryInstance, entity: Entity): boolean {
+    const { required, forbidden, or } = query.predicates;
+    for (const predicate of required) if (!predicateMatches(world, entity, predicate)) return false;
+    for (const predicate of forbidden) if (predicateMatches(world, entity, predicate)) return false;
+    if (or.length && !or.some((predicate) => predicateMatches(world, entity, predicate))) return false;
+    return true;
