+            let states = query.predicateStates.get(predicate);
+            if (!states) query.predicateStates.set(predicate, (states = []));
+            const eid = getEntityId(entity);
+            const previous = states[eid] || false;
+            const current = predicateMatches(world, entity, predicate);
+            states[eid] = current;
+            if (type === 'add') trackingMatches &&= !previous && current;
+            else if (type === 'remove') trackingMatches &&= previous && !current;
+            else trackingMatches &&= previous !== current;
+        }
